#include <locale.h>
#include <stdio.h>
#include <wctype.h>
int main(void) {
  if (!setlocale(LC_ALL, "C.UTF-8")) return 1;
  int beginning = -1;
  int emitted = 0;
  putchar('[');
  for (int point = 0; point <= 0x110000; point++) {
    int printable = point < 0x110000 && iswprint(point);
    if (printable && beginning < 0) beginning = point;
    if (!printable && beginning >= 0) {
      printf("%s%d,%d", emitted++ ? "," : "", beginning, point - 1);
      beginning = -1;
    }
  }
  puts("]");
  return 0;
}
